'use strict';

// @postalsys/email-text-tools ships jsdom and juice, with everything they load, as bundles in its
// own dist/vendor directory, so `npm ls` never lists those packages. list-generate.js reads them
// from the bundles' package lists; this keeps the committed static/licenses.html from losing them
// (it is regenerated by `npm run update`, so a stale listing means a dependency bump that skipped it).

const test = require('node:test');
const assert = require('node:assert').strict;
const fs = require('fs');
const pathlib = require('path');

const root = pathlib.join(__dirname, '..');
const vendorDir = pathlib.join(pathlib.dirname(require.resolve('@postalsys/email-text-tools/package.json')), 'dist', 'vendor');

test('every package bundled into a dependency is in the license listing', () => {
    const html = fs.readFileSync(pathlib.join(root, 'static', 'licenses.html'), 'utf-8');
    const lists = fs.readdirSync(vendorDir).filter(name => name.endsWith('.packages.json'));
    assert.ok(lists.length >= 2, `bundle package lists in ${vendorDir}: ${lists.join(', ')}`);

    const missing = [];
    for (const list of lists) {
        for (const { name, version } of JSON.parse(fs.readFileSync(pathlib.join(vendorDir, list), 'utf-8'))) {
            if (!html.includes(`<span class="name">${name}</span>\n<span class="version">${version}</span>`)) {
                missing.push(`${name}@${version} (${list})`);
            }
        }
    }
    assert.deepEqual(missing, [], 'run npm run licenses');
});
